// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address user) public {
        vm.assume(amount1 <= type(uint256).max - amount2);
        vm.assume(user != address(0));
        vm.deal(user, amount1 + amount2);

        vm.startPrank(user);
        c.addToBalance{value: amount1}();
        c.addToBalance{value: amount2}();
        vm.stopPrank();

        assertTrue(c.getBalance(user) == amount1 + amount2);
    }
}
